Fl_Scroll *br_winfolderlist=(Fl_Scroll *)0;

Fl_Window* make_folderlist_window() {
  Fl_Window* w;
  int USELOCALE = atoi (PREFERENCES.Get_char_tree ("postoffice/international/uselocale"));
  char *LANGUAGE = PREFERENCES.Get_char_tree ("postoffice/international/language");
  Var *CLOCALE = PREFERENCES.Get_collection ("locale")->Get_collection (LANGUAGE)->Get_collection ("postoffice");
  { Fl_Window* o = new Fl_Window(174, 223, "Mailboxes");
    w = o; (void)w;
    { Fl_Button* o = new Fl_Button(0, 0, 175, 20, "Mailboxes");
      o->box(FL_THIN_UP_BOX);
      o->labelsize(12);
      o->align(Fl_Align(FL_ALIGN_LEFT|FL_ALIGN_INSIDE));
      xloc(o, "mailboxes");
    } // Fl_Button* o
    { br_winfolderlist = new Fl_Scroll(0, 20, 175, 205);
      br_winfolderlist->type(2);
      br_winfolderlist->box(FL_DOWN_BOX);
      br_winfolderlist->color((Fl_Color)55);
      br_winfolderlist->labelsize(12);
      br_winfolderlist->end();
      Fl_Group::current()->resizable(br_winfolderlist);
    } // Fl_Scroll* br_winfolderlist
    xloc(o, "mailboxes");
    o->end();
  } // Fl_Window* o
  return w;
}

