Fl_Window* make_exitwindow() {
  { win_exit = new Fl_Window(279, 100, "Post Office Shutdown");
    { Fl_Group* o = new Fl_Group(0, 0, 280, 100);
      o->image( image_bg() );
      o->align(Fl_Align(FL_ALIGN_CENTER|FL_ALIGN_INSIDE));
      { Fl_Button* o = new Fl_Button(18, 10, 50, 50);
        o->box(FL_NO_BOX);
        o->image( image_shredder2() );
      } // Fl_Button* o
      { Fl_Button* o = new Fl_Button(80, 15, 170, 40, "Taking \'special care\' of your mission critical mail data.");
        o->box(FL_BORDER_FRAME);
        o->color(FL_FOREGROUND_COLOR);
        o->labelsize(12);
        o->align(Fl_Align(FL_ALIGN_WRAP));
      } // Fl_Button* o
      { bt_exitline = new Fl_Slider(10, 69, 260, 21);
        bt_exitline->type(3);
        bt_exitline->box(FL_THIN_DOWN_BOX);
        bt_exitline->color((Fl_Color)53);
        bt_exitline->selection_color((Fl_Color)51);
        bt_exitline->labelfont(1);
        bt_exitline->labelsize(10);
        bt_exitline->maximum(100);
        bt_exitline->align(Fl_Align(FL_ALIGN_CENTER|FL_ALIGN_INSIDE));
      } // Fl_Slider* bt_exitline
      o->end();
    } // Fl_Group* o
    win_exit->set_modal();
    win_exit->end();
  } // Fl_Window* win_exit
  return win_exit;
}

